  async function checkReminders(){if(!('Notification'in window)||Notification.permission!=='granted')return;const now=new Date(),rows=(await all()).filter(r=>r.reminder&&['tareas','eventos'].includes(r.type)&&r.date===today()&&r.time),keyBase=today();for(const r of rows){const when=new Date(`${r.date}T${r.time}`),trigger=new Date(when.getTime()-Number(r.reminderMinutes||0)*60000),delta=trigger-now;if(delta>=0&&delta<60000){const key=`vida-reminded-${keyBase}-${r.id}-${r.time}-${r.reminderMinutes||0}`;if(!localStorage.getItem(key)){try{new Notification(r.title||'Recordatorio de VIDA',{body:r.reminderMinutes&&Number(r.reminderMinutes)>0?'Aviso previo a '+r.title:(r.type==='tareas'?'Tarea pendiente':'Evento próximo')});localStorage.setItem(key,'1');}catch(err){console.warn('El navegador no pudo mostrar el recordatorio.',err);}}}}}
